import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static int[] parentArray;
    static int totalComponents;

    static int findParent(int x) {
        if (parentArray[x] == x) return x;
        parentArray[x] = findParent(parentArray[x]);
        return parentArray[x];
    }

    static void unionSets(int a, int b) {
        a = findParent(a);
        b = findParent(b);
        if (a == b) return;
        totalComponents--;
        parentArray[b] = a;
    }

    static long modPow(long base, int e) {
        if (e == 0) return 1;
        long half = modPow(base, e / 2);
        long res = (half * half) % MOD;
        if ((e & 1) == 1) res = (res * base) % MOD;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(modPow(p, (int)(p - 1)));
            sc.close();
            return;
        }

        totalComponents = (int)(p - (k > 1 ? 1 : 0));
        parentArray = new int[(int)p];
        for (int i = 1; i < p; i++) {
            parentArray[i] = i;
        }

        for (int i = 1; i < p; i++) {
            unionSets(i, (int)((i * k) % p));
        }

        System.out.println(modPow(p, totalComponents));
        sc.close();
    }
}
